def create_agent_role() -> None:
    """The least-privilege login used by the agents' MCP server (Postgres only)."""
    password = os.environ.get("AGENT_DB_PASSWORD")
    if op.get_bind().dialect.name != "postgresql" or not password:
        return
    pw = password.replace("'", "''")
    op.execute(f"""DO $$ BEGIN
        IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = '{AGENT_ROLE}') THEN
            CREATE ROLE {AGENT_ROLE} LOGIN PASSWORD '{pw}';
        ELSE
            ALTER ROLE {AGENT_ROLE} LOGIN PASSWORD '{pw}';
        END IF; END $$""")
    op.execute(f"GRANT SELECT ON {', '.join(AGENT_SELECT)} TO {AGENT_ROLE}")
    op.execute(f"GRANT INSERT ON {', '.join(AGENT_INSERT)} TO {AGENT_ROLE}")
    op.execute(f"GRANT UPDATE (audit) ON submissions TO {AGENT_ROLE}")
    op.execute(f"GRANT USAGE ON {', '.join(t + '_id_seq' for t in AGENT_INSERT)} TO {AGENT_ROLE}")


